pub fn dispatch_random_tick(
    level: &mut dyn LevelHost,
    mods: &[Box<dyn Hooks>],
    ticks: &mut Ticks,
    dimension: LevelDimension,
    pos: BlockPos,
    state: BlockStateId,
    handled: &mut bool,
) {
    if *handled {
        return;
    }
    for m in mods {
        if matches!(
            m.random_tick(level, &mut *ticks, dimension, pos, state),
            Flow::Cancel
        ) {
            *handled = true;
            break;
        }
    }
}
