pub fn dispatch_update_shape(
    level: &dyn LevelHost,
    mods: &[Box<dyn Hooks>],
    ticks: &mut Ticks,
    dimension: LevelDimension,
    pos: BlockPos,
    state: BlockStateId,
    direction: Direction,
    neighbour_pos: BlockPos,
    neighbour: BlockStateId,
    new: &mut Option<BlockStateId>,
) {
    if new.is_some() {
        return;
    }
    for m in mods {
        if let Some(value) = m.update_shape(
            level,
            &mut *ticks,
            dimension,
            pos,
            state,
            direction,
            neighbour_pos,
            neighbour,
        ) {
            *new = Some(value);
            break;
        }
    }
}
